-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[90866] = { id = 90866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Universal Language", description = "To go home, water of life. Need.\n\n<Tul'amar attempts to discern if you understand what she's talking about with a look. After a pause, she opts to stab her own fingertip with the end of her staff and then displays a bead of her blood to you.>\n\nThis. Of here. Is of fight. Of fight is Void. Void is power. With power, go home.\n\n<She shows her fangs with an exaggerated snarl before pantomiming a claw swipe.>\n\nWater of life. Of beast. Much. Yes?", progress = "You. Not die? Good.", completion = "Blood! Is blood. Yes?\n\n<She looks to one of her kin, who assures her that she's got the right word this time.>\n\nGood. Now see.", objectives = "Collect blood from the beasts north of the Night Trench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90867] = { id = 90867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Darkness, Light", description = "We will not let the Sunwell be corrupted again. This Darkwell must change, but it must change to something that we are no longer bound to with such dependency. We do not need this well to be the bait for so many other world-corrupting forces.\n\nNo, today we heal the Darkwell, and make it something new. Let me know when you are ready.", sourceObjective = "Conduct the ritual to cleanse the Darkwell.", completion = "Behold the Dawnwell. May its waters never know corruption. May it stand as a reminder of all that we have lost, and an inspiration for what we can become.", sourceObjectiveStatus = "unverified-source-field" }
quests[90869] = { id = 90869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All in the Image", description = "So, the higher-ups in the marketing department say you need a good partner to soften your aesthetic of... you know, \"murder everyone around me for gold.\"\n\nWe've got two focus group approved goblins over there ready to go, so go take your pick. Sassy will handle the paperwork.\n\nOh, don't give me that look. You only gotta forever-love each other in front of the public. Once the cameras are off, no one cares. It'll be great for your reputation!", progress = "C'mon, this ain't rocket surgery. Pick whoever you wanna pose on some magazine covers with.", completion = "There we go! Nice and artificial, just like all the best marketing should be.\n\nAnd I just finished the paperwork for your other big image upgrade. I think you're really going like this!", objectives = "Speak to Sassy Hardwrench to select a \"marketing partner.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90870] = { id = 90870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Grub", description = "Ah, ye're here! Brewfest is here and we've got a small problem. We can't have a proper feast without the food, but some pesky hozen thought it'd be fun to steal our bags of grub. I'm sure they're just lookin' to fill their own bellies, but it's messin' up our plans!\n\nSo here's what I need ye to do: hunt down those hozen and take back the bags they've snatched. There's a good chance ye'll find a few bags just sittin' on the ground too. When ye return, just add the recovered bags to that wagon back there.", progress = "The feast won't come together without those ingredients!", completion = "Ah, ye've done it! The cooks will be pleased.", objectives = "Collect Bags of Brewfest Ingredients and deposit them at the wagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90871] = { id = 90871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silversun Compact", description = "Champion. \n\nAfter much discussion, negotiation, and even some screaming and three duels, the Sunreavers and the Silver Covenant have decided on a course of action to define both of our futures.\n\nGiven your aid in getting us to this day, we would like you here to act as a witness as we formalize and sign our peace accords. Will you do us the honor of igniting the Flames of Remembrance?", sourceObjective = "Assist in the formalization of The Silversun Compact.", progress = "Strange times. Strange times indeed.", completion = "It is done. Today marks the first day of the Silversun Compact. May the oaths we sign ourselves to today bind us in trying times to do the right thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[90872] = { id = 90872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drenched In It", description = "<Tul'amar looks away from the blood-soaked and mortified Juras, and toward the portal as it flickers to life. She reads it with her powers of the arcane.>\n\nGood. Blood is vio... violent? Violent is power. Need more. Now, brothers and sisters.\n\n<She gestures to the blood in your possession, and then to her people. Many of them return wary looks your way.>\n\nYou can. I say. \n\nThen, go out. See of me.", progress = "Done?", completion = "Good. Now, more. Brothers and sisters, help.\n\nAnd men of Void, kill.", objectives = "Mark 8 Offworld Refugees with Predator Blood to empower the portal in Exiles' Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90873] = { id = 90873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "These Violent Delights", description = "Brothers and sisters. Here. Help.\n\n<Tul'amar connects her thumb and index finger on both hands to make a chain. Then, she breaks the link with a sharp gesture.>\n\nHow? Show.\n\n<She then produces a glimmering relic and holds it over her gauntlet. She spends a portion of her arcane energy into it. Its newly activated magic forces the straps holding her glove in place loose.>\n\nUse.", completion = "<Tul'amar tilts her head at the freed draenei hiding behind her.>\n\nI see. Good. You good.", objectives = "Use the Relic of Liberation to free 10 Master's Prospects and 3 Unwilling Summons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90874] = { id = 90874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Violent Ends", description = "Go home. How?\n\n<She offers a dramatic flourish with her fingertips, producing some arcane sparks. Then, she makes an X with her index fingers.>\n\nOf me? No. Of they.\n\n<Tul'amar gestures to a group of voidwalkers up ahead. She then draws her thumb across her neck.>\n\nKill. And.\n\n<She reaches into a pouch on her hip and retrieves a cracked stone of domanaar make. It looks like a spell reagent of some kind.>\n\nAs this. Need.", progress = "<Tul'amar holds still, even as you approach.>", completion = "<She counts out the portal runes in your possession and nods in approval.>\n\nYes. Good.", objectives = "Collect 8 Abductor's Marks from the voidwalkers of Masters' Perch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90875] = { id = 90875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across Worlds", description = "Man of Void. Have key. Need. Key to home.\n\n<Tul'amar gestures down the way to the northwest. She grimaces back at her injured kin.>\n\nGo back, we. Wait. Hope. For you.", progress = "<Tul'amar smiles sadly at her people.>", completion = "Stay. I must. Men of Void, cannot find brothers and sisters. Finish, must. Only I.\n\nYou, good. Friend. But. Trust, can't. Trust, only when brothers and sisters safe.\n\n<She then holds her staff forward, offering it to Juras. Though he seems reluctant to take it, Tul'amar does not waver.>", objectives = "Kill Snaerius and recover his Lodestar of the Great Dark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90876] = { id = 90876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reluctant Hand", description = "Champion, I felt it was important to have you here for this moment so that neither I nor my wayward former peer get off topic with his many failings.\n\nI also want a witness in case he turns to evil. \n\nWould you be so kind as to unpack a few items so that I do not have to touch them?", sourceObjective = "Assist in preparing the Umbral Atrium.", progress = "I am not so filled with pride that I cannot admit to some... mild nostalgia for the banter I once enjoyed with my former peer. \n\nMagister Umbric was once quite the source of counterpoints and suggestions that went beyond expectations, and helped push our knowledge of magic further and further.", completion = "So, we help save the city and in return, I'm allowed to have my old things back.\n\nFrom anyone else, that would be an insult. From Rommath? The highest of praise.\n\nOh, he even kept my old alembic... how thoughtful.", sourceObjectiveStatus = "unverified-source-field" }
quests[90879] = { id = 90879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewmaster's Kitchen", description = "Now that ye've gathered the materials, we can get to cookin'! We'll need plenty o' food for the whole crowd.\n\nWe've got a short but sweet menu: Barley Soup, Pretzels, and of course a good ol' brew!\n\nAre ye ready to learn the ropes?", progress = "Get cookin'!", completion = "Ah, I can smell the pretzels from here. Ye've cooked up a spread that'll keep even the pickiest dwarves satisfied!", objectives = "Follow the steps to cook Brewfest food and a delicious Brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90880] = { id = 90880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serving with Style", description = "Ye've done well in the kitchen, now it's time to learn how to serve! Brewfest isn't just about food--it's about makin' sure everyone has a good time.\n\nYe'll be takin' orders, deliverin' dishes, and pourin' drinks with a smile.\n\nGet out there and show 'em how it's done. Brewfest won't run without good service!", progress = "Remember to serve with a smile!", completion = "I'd say ye've earned yerself a nice break and a brew after all of yer hard work. But don't get too relaxed! There's still plenty to do to keep Brewfest runnin'!", objectives = "Take the customer's order and serve the food to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90882] = { id = 90882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnoll Way", progress = "Handle those gnolls while we figure out our next move.", completion = "Excellent job. However, we cannot rest.\n\nWe have word of more chaos in the highlands.", objectives = "Slay 10 gnolls within Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90883] = { id = 90883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Go'shek Farm", progress = "Find Farmer Bruvk outside of Go'Shek Farm.", completion = "I never thought I'd get this much help! Please, you have to stop them!", objectives = "Travel to Go'shek Farm", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90885] = { id = 90885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Beautiful Pumpkins", description = "The kobolds and ogres appeared out of no where and kicked us out of the farm!\n\nI thought this was some Alliance plot until you all showed up. Maybe the Alliance is here to help us after all.\n\nYou have to help me get my precious pumpkins back. I've spent the entire harvest cultivating them!\n\nYou lead the way. I'll grab the pumpkins when you find them.", progress = "Return to Thrall with Farmer Bruvk and his pumpkins", completion = "That's... quite a lot of pumpkins.\n\nI think our farmer friend should take them back to Hammerfall. Horde reinforcements should be there by now.", objectives = "Recover 4 Prized Pumpkins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90886] = { id = 90886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Laid Plans of Kobolds and Ogres", description = "The kobolds and ogres here seem to be carrying some sort of plan for their attack.\n\nI don't think they're particularly well written, so I'll need several of them to figure out what the ogres are planning.", progress = "Did you recover the plans? They should be on most of the foes within the farm.", completion = "Just as I thought.\n\nI can barely read any of this.", objectives = "Collect 7 Poorly Written Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90887] = { id = 90887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmer's Nemesis", description = "Farmer Bruvk mentioned an ogre named Runk was leading the group here.\n\nThese creatures won't leave this place as long as that ogre is commanding them.", progress = "We'll stay here and guard the remaining farmers while you handle Runk.", completion = "This should help disperse the creatures. Without a leader they'll flee when Alliance and Horde reinforcements show up.", objectives = "Slay Runk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90888] = { id = 90888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Stromgarde Keep", description = "The plans you found indicate the ogres are trying to get food to supply a massive attack on Stromgarde Keep!\n\nOr they're trying to use the crops to keep guarding an object named a storm. The translation was loose. \n\nIt's safe to assume our problem is the former. Let's go!", completion = "This looks bad, but it's nothing we can't handle.", objectives = "Travel to Stromgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90889] = { id = 90889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tale of the Echoes of Sai'alyo" }
quests[90892] = { id = 90892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Skies: A Fel of a Time", description = "<The skies are full of residual time energy and demons pouring in from other timelines.\n\nI should help Eternus by cleaning up the skies. The extra bronze energy would be nice too.>", completion = "<The skies are a little clearer now. The infinites might be interested in trading with this extra bronze I've collected.>", objectives = "Collect bronze by flying through 10 Lost Legion demons and 25 Motes of Bronze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90893] = { id = 90893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repelling the Siege", description = "We must do everything possible to stop this siege on Stromgarde. \n\nMake your way into the battle and weaken the ogre forces.\n\nStromgarde should be able to rally if they can gain the upper hand.", completion = "The siege is at an end. We've got their leader cornered.", objectives = "Repel the Ogre Siege outside of Stromgarde keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90895] = { id = 90895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catapult Bombardment", description = "These catapults are relentless. They must be destroyed.\n\nPlace these rune stones at their base. It'll unleash arcane magic to turn the catapults to dust.\n\nI'll take out a few as well as I make my way across the battlefield.", completion = "With the catapults gone the soldiers of Stromgarde should be able to gain the upperhand.", objectives = "Apply Jaina's Runes to 4 Catapults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90896] = { id = 90896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Ogre", description = "The head of the siege is still cowering within the former Horde encampment. \n\nHe managed to hide from Jaina's spell behind several of his cohorts.\n\nYou can have the honors to confront of him. Jaina and I will stay here to ensure any remnants of the siege do not return.\n\nEnd this.", progress = "Defeat Ro'grok and end this siege.", completion = "The siege is over. Arathi Highlands will hopefully return to a somewhat peaceful state now.", objectives = "Slay Ro'grok", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90897] = { id = 90897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Stromgarde", description = "I think we can count ourselves lucky there was no bigger threat here beyond a group of overambitious ogres. \n\nThe same can't be said of other threats that are looming throughout Azeroth.\n\nCome. Let's return to Stromgarde to discuss matters further.", completion = "It's good to see the people here in high spirits.", objectives = "Meet Jaina Proudmoore within Stromgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90898] = { id = 90898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Hammerfall", description = "We're not always so lucky that a plan such as this is ended so swiftly and without a surprise portal or two.\n\nThat being said, more dangers lurk throughout Azeroth. I know you can be of help to some.\n\nLet us return to Hammerfall to see how they're recovering.", completion = "Hammerfall will recover in time and become stronger than it was before.", objectives = "Return to Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90901] = { id = 90901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As A Matter of Artifact", description = "There's more to artifacts than meets the eye, {name}.\n\nSimply using an artifact allows its legend to grow, and as that legend grows, so too does its power.\n\nIn order to unlock the full potential of that power, however, you'll need to focus infinite power into the artifact's traits. As more traits are empowered the artifact's true potential will be unlocked, and its legend will be undeniable.\n\nLet's get started.", progress = "Unlocking the full potential of your artifact will be key to understanding their impact on this timeline.", completion = "As you gather infinite power do not forget to focus it into your artifact.\n\nThe more power you invest, the swifter you will gather more infinite power and grow your artifact's legend--and your own.", objectives = "Unlock artifacts traits using Infinite Power gained from looting Epoch Mementos from any enemy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90907] = { id = 90907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First to Know", progress = "I hope our fair town is treating you well. If you have any concerns at all, bring them to me.", completion = "It is heartening that you trust me with these serious concerns.", objectives = "Inform Lord Antenorian, governor of Tranquillien, of your investigation results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90910] = { id = 90910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelming Darkness", description = "A dreadful presence calls from the den just to the southeast of here. Many of the dazed ren'dorei you see in camp were overwhelmed by its raw power on a scouting mission.\n\nLet us go together and see if whatever dwells within can be put to use. We cannot afford to spurn power in the fight against Xal'atath.\n\nBefore that: we have little need of Kalgorg. The Voidstorm has made my voidwalker unruly and disobedient. Assist me in sacrificing it. We will need all of the Void energy we can muster.", progress = "Disobedient little...", completion = "Kalgorg descended here, but I won't confront it unprepared.\n\nThat disobedient little monster. It thinks it can simply walk away after two decades?", objectives = "Sacrifice Kalgorg and then meet Lucia Nightbreaker in the Den of Predaxes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90911] = { id = 90911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Next Adventure", objectives = "Choose your next adventure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90914] = { id = 90914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Born Killer", description = "Ah, {name}. I have so enjoyed our time together. I hunger for more. \n\nI wish you knew more of me than my predilection for the taste of mortal suffering. One of my greatest joys is in crafting Void power into various objects and structures. It is my passion--my art.\n\nHere, I would like to show you. First, we will need power. You already know how to get it, of course: kill, kill, kill.", progress = "What an odd feeling. I feel almost... drawn to you. It must be your mesmerizing presence.", completion = "My, what delightfully gruesome success. \n\nI am interested to work together with you. You should know more of our people, and see more of my abilities.", objectives = "Collect 15 Void Essence from monsters around Voidstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90915] = { id = 90915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifice of Aggression", description = "While we domanaar are best known for leading armies and savoring battles, there is more to us. \n\nMany, like myself, enjoy using our mastery over the Void to shape it into the buildings and objects you see around you. \n\nHow do you think Xal'atath learned to create that great tower of hers? She's a quick study. \n\nCome now, and I will show you my work.", progress = "How excellent to spend some time together. You mortals are so very interesting... you most of all.", completion = "Consider this blade my gift to you. We shall work together to make you into a true weapon of destruction.", objectives = "Craft a blade with Decimus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90916] = { id = 90916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek to Destroy", description = "It's no easy thing, intertwining Light and Void together. The result is unstable, so we must continue to temper it. \n\nWe shall quench this blade in the blood of our enemies. \n\nSome domanaar attempt to reclaim and re-power Nexus-Point Xenas. That won't be good for your people. I'll assume you want to stop it. \n\nWhat is it you mortals say? Two birds, one stone?", completion = "These Nexus-Points used to be fonts of power for us domanaar to enjoy, long before Xal'atath overthrew us. \n\nSomeday, they shall be so again.", objectives = "Meet Decimus at Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90917] = { id = 90917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvester of Savagery", description = "The blade hungers! The blood of our enemies will help stabilize and hone our nascent weapon. \n\nYou'll need to drench the blade inside some corpses. So, you'll need to make corpses. \n\n<Decimus's smile grows broader.> \n\nYou're good at that, right?", progress = "The monsters native to this land are fierce and violent. Their bloodlust drew the Void here, so naturally... we feel quite at home here.", completion = "Very good. \n\nI understand you mortals fret over things like ecological balance and culling of species. \n\nFear not: the monsters here are as endless as they are brutal.", objectives = "Use the Nascent Blade on corpses in Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90918] = { id = 90918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unforgiven", description = "Since even before our little misadventure, Nexus-Point Xenas has always been the weakest link. The beasts here are stubborn and powerful, always pushing deeper and deeper in. \n\nSome domanaar seek to reclaim the Nexus-Point. They are known to me: weaklings, fighting for scraps. Let's ensure they fail.", completion = "Ah, how quaint, to catch up with old enemies. \n\nWe domanaar once had intricate structures of power. Each domanaar fights for their own sake alone, but it is often advantageous to align oneself with others. Temporarily, of course. \n\nThe most powerful among us were the High Lords. When Xal'atath arrived... she made an example of them all. The spectacle was so moving, it drew not only fear but something closer to loyalty from us domanaar. \n\nSome, though not all.", objectives = "Slay Noxian, Averus, and Tenebre around Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90919] = { id = 90919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fiend That Failed", description = "The blade squirms. It is ready for its next transformation.\n\nThere is only the leader, Vortensiun, left. \n\nHe is known to me. Once, we formed a pact together to defeat a rival. When the time came for him to betray me, he did so clumsily. \n\nI let him live, so I could savor the taste of his regret. \n\nI wonder how well that pain has marinated by now? Let's find out. When the blade is tempered in his essence, it shall grow new power.", completion = "Pay no mind to Vortensiun's comment about food. \n\nWe are becoming good friends, are we not?", objectives = "Slay Vortensiun in Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90920] = { id = 90920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warmth for the Soul", description = "Enjoying the view? \n\nThe blade is stronger now, but it is not yet complete. A weapon worthy of you deserves nothing less than perfection. \n\nBut let us relax for a moment. I understand you mortals enjoy a... casual exchange of conversation to get to know each other better.\n\nI am familiar with the concept, but am curious to see it in action. Indulge me?", completion = "Fascinating, how freely you give up delicate information about yourself.\n\nI choose to believe you would not lie to me, of course. We are friends now, you and I. Such a mortal concept intrigues me.", objectives = "Enjoy a pleasant conversation with Decimus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90922] = { id = 90922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Wake", description = "<The shade flickers. You can barely make out its whisper.>\n\nYou... left me... to die...\n\n<Its arm reaches toward you, then dissipates. Somehow, the presence is a familiar one. You feel that you know this spirit. \n\nYou see more flickers in the distance. What are these shades?>", progress = "Such a strange and terrible place. Fear not--if you wish to converse more to settle your nerves... I am here for you.", completion = "I'm terribly sorry you had to go through that. The words of these spirits have upset you, correct?\n\n<Decimus peers at you.>", objectives = "Dispel spirits in the Gnawing Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90923] = { id = 90923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shepherd of Fear", description = "Our journey continues... one final battlefield. There are vicious beasts aplenty here. Their Void shall fuel the blade even more.\n\nAnd the blade's newfound power shall draw their Void into itself by mere proximity!\n\nThough, this place is different. You may find things you don't expect.\n\nKeep an eye out.", progress = "Don't get distracted, now. This will all be worth it when you have a mighty weapon to hold.", completion = "At long last...", objectives = "Slay monsters and gather Void Essence in the Gnawing Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90924] = { id = 90924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wicked End", description = "The time has come. The final step. \n\n<Decimus pauses, savoring something.>\n\nLet us create the greatest weapon your kind has ever seen.", completion = "The blade, as promised. See? I never meant to keep it for myself. I will even shape it into whichever form suits you best.\n\nThe taste of your suffering was all I desired.", objectives = "Complete the forging of the blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90938] = { id = 90938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Skip Through the Void", description = "Fleshling, do you know about Untethered Space? I am sure you know someone who has encountered it. \n \nPreviously we assumed that only beings of energy such as those from K'aresh could Phase Dive. Since the Harbinger's return, she has created a means for solid creatures to become energy using Reshii Wraps.\n \nMy name is Hashim, and I have some Reshii Wraps in my possession. We are in desperate need of adventurers powerful enough to brave the lucrative depths of Untethered Space.", completion = "I can provide you with everything you need to explore Untethered Space.", objectives = "Meet Hashim at Overlook Zo'Shuul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90943] = { id = 90943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormarion Assault" }
quests[90957] = { id = 90957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Initiation Day", description = "{name}, today is when you find your proper place among the haranir.\n\nRoot Tender Dalnir will guide you. His path is one of tradition and humility, so don't expect excitement. By the end of the day, you will make your mark in the Den of Remembrance. The story you begin now will build on those that came before, like the roots themselves, growing the foundations of Harandar.\n\nDalnir was clearing invasive drifters from the roots. Before you go to him, aid Dalnir by removing some of the pests yourself.", completion = "The time has come to take your place among our people, and give up childish adventures. Follow my guidance and Aln'hara bless this day.\n\nRemember, our traditions show us the way.", objectives = "Elder Hagar is asking you to kill 6 Invasive drifters from around the roots of Teldrassil, and then meet with Root Tender Dalnir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90958] = { id = 90958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roots Above All", description = "Some say the great trees grow, and Harandar will remain even if we do not tend them. Our traditions say, it does not matter. We remain here to protect, tend and serve. We do this with dedication and humility.\n\nKeeping the environment around the roots clean and free of pests reflects upon this duty. Return to me once you are done. You will represent our ways well, {name}.", progress = "Have you performed the tasks that I have asked for?", completion = "Is that an outsider's gear? You were aiding Orweyna with these--distractions, instead of your duties. How will you maintain our traditions if you can not follow my guidance through the ceremony?\n\nI will speak to Elder Hagar. Remember the importance of this day and your duty.", objectives = "Root Tender Dalnir wants you to pull weeds, remove mud skippers and invasive fungi from the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90959] = { id = 90959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traditional Duties", description = "Dalnir has a point about the ceremony, but we should not focus too narrowly. I still hold the values of our people, but sometimes we must look beyond.\n\nDo not worry. You should be focusing on the ceremony. I will search for the outsiders later.\n\nI am sure you could join me once the initiation ceremony is done.", completion = "The outsider told us of your actions. \n\nYou must understand, {name}, though it was courageous, it was dangerous, even for you.\n\nI know Dalnir is furious, but Hagar understands your desire to help.", objectives = "An inner voice is telling you to search for the outsider in Har'mara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90960] = { id = 90960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Story, My Legacy", description = "{name}, the final part of the ceremony is ahead of you, though you've put it at risk with your digressions.\n\nThe first mural will show you a vision of your true self, the one that resonates from within you.\n\nThe second mural will show you a vision of where you are needed.\n\nThe third mural, tradition tells us, breaks the barrier between us and the Goddess herself.\n\nThe ceremony will conclude with you painting your story in the Den.", progress = "Take your time, {name}. The ceremony is not about how fast you do it, but about what you learn from it.", completion = "In all my years of initiations, this has to be a first. It seems that the Goddess herself has noticed you.\n\nI am sensing a mysterious and bountiful journey ahead of you.", objectives = "Elder Hagar asked you to commune with the three murals, and then paint your own story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90961] = { id = 90961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a New Land", description = "{name}, I see you now for who you are. You are dedicated not just to our people, but to the world.\n\nThe goddess has acknowledged you as well, and I can not recall such an event -- not even Orweyna's ceremony was so eventful.\n\nThis is where your story begins. It is time for you to take the first steps of your journey.", completion = "So you are {name}? \n\nI never thought a {race} would show up in the city. With that, Your actions precede you. \n\nI have arranged some basic gear for you. It is the least I can do for saving one of us.", objectives = "With the conclusion of the ceremony, it is now time to start your journey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90962] = { id = 90962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormarion Assault" }
quests[90963] = { id = 90963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caves of the Cleft", description = "Good work freeing the captured rutaani. With the seeds you recovered, I can try to carry on Ru'gar's work.\n\nI did some scouting and gathering while you were keeping the fungarians distracted, and could use your help with another task. Meet me at the cave northeast of here.", completion = "This seems to be a safe location from which to plan our next moves, and one of the plants Ru'gar mentioned to me grows in this area as well.", objectives = "Meet Ney'leia near the northeastern cave in Fungal Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90968] = { id = 90968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanic Rumblings", description = "Rumors are abuzz of titan forces being sighted around Khaz Algar. Brann has asked Dagran Thaurissan II for assistance in looking into these rumors.", completion = "If these rumors are true, we must investigate.", objectives = "Seek out Dagran Thaurissan II at the Delver's Headquarters in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90969] = { id = 90969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titan Consoles", description = "Adventurer, the rumors are true. I've seen the titan forces and they are nae friendly. We must try tae discover why they are emergin' now and try and stop 'em from doin' too much damage.\n\nConfront and stop these renegade constructs. To help ye, I've procured some Titan Consoles. I was able to set them up in the affected areas. I can use them to communicate with ye in the field. I am thinkin' we can use them to counter these titan forces as well.", completion = "{name}, these consoles are bein' overloaded by the titan's presence. If we can defeat them and secure titan discs, I think we can use 'em to empower the console to grant ye boons within the space. The boons can aid you in pushing back these rogue titan constructs.", objectives = "Seek out one of Dagran's Titan Consoles in an Overcharged Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90970] = { id = 90970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titan Disc-Count", description = "We need tae secure more titan discs. Venture deeper into this area, seek out the Titan Constructs, and defeat them. Ye should find disc shards. This console can reassemble them and access their data. \n\nMake sure tae search for any treasure rooms as well. The constructs appear to be assistin' the local denizens. Some of those locals might've secured additional titan discs with their other treasures.", progress = "Adventurer? Is that you?", completion = "Did ye find the shards? While ye were away, I remembered I'd found some on my visit to that location. Ye should find them in a pouch I hid next to the console.", objectives = "Secure Titan Disc Shards and dispatch Titan Constructs within the delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90971] = { id = 90971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overcharged Console", description = "With the shards ye found, we can use the console tae restore the titan discs and use them to access powerful boons. \n\nUse the console's disc repair feature to create a titan disc, then use that disc to select a starting node in the overcharge console's interface.", progress = "Did it work?", completion = "My remote console shows that there was a change. The overcharged console is funnelin' excess energy to a new node. This should grant ye that node's power when venturin' intae other areas where the titan constructs have emerged.\n\nWe'll use the titan force's own energy against 'em!", objectives = "Restore a Titan Disc and then spend it to unlock one of the starting nodes in the Overcharged Console Tech Tree.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90972] = { id = 90972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Common Cause", description = "{name}! I heard you were here on K'aresh. Good. I need help.\n \nMy apprentice Leona has been researching novel means of harnessing the power of the Void. She's approached a Demon Hunter named Adarus to see if the Illidari's methods could offer any insights.\n \nTo be honest, I'm not sure I trust Adarus. He's not... studious. Unlike Leona.\n \nLeona was just going to observe him as he sought to master the Void. But she's disappeared. Please find her. Talk with Adarus--he knows something.", progress = "Have you spoken to Adarus yet, {name}? It's clear that the Illidari's apotheosis has stripped them of their manners.", completion = "Adarus sent you? \n\nHis lack of faith in my abilities and desire to delegate speak volumes.", objectives = "Speak to Adarus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[90993] = { id = 90993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take the Darkwell!", description = "We have our army but what lies behind these walls are the most powerful, most vile, and most empowered foes Xal'atath has in her arsenal. \n\nGather your strongest allies, {name}, and meet us within. It is time to end this and take back our well.", sourceObjective = "March on Quel'Danas.", sourceObjectiveStatus = "unverified-source-field" }
quests[90995] = { id = 90995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of The Fel Hammer", description = "Oh wait! Of course, right when I send you off I remember the most important thing!\n\nThe you-of-this-timeline made a critical choice for the future of all demon hunters. The follower they chose to be their personal champion created two diverging timelines for the fate of the Illidari.\n\nYou will need to choose which of these diverging timelines to explore. What rings true to you?", progress = "Have you made a choice?", completion = "Very well, we will study this version of the timeline. Let us see what the Illidari hold in their future--err, past.", objectives = "Choose your personal champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91000] = { id = 91000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Humble Servant", progress = "There is much to do, {name}.", completion = "Good work, {name}. Things are starting to look better.", objectives = "Aid the people of Hammerfall in their recovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91001] = { id = 91001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear de Way", description = "With dey magic and dey line broken, de Twilight's Blade is losin' ground.\n\nWe must take advantage of dey turned backs.\n\nI will lead de charge through de ravine to de Conquerer's Sanctum beyond. Mor'duun is there, keepin' his coward-body safe from our spears and axes.\n\nHe won't be safe much longer.", progress = "We must act--now!", completion = "Mor'duun may laugh now, holed up in de Sanctum.\n\nBut we will get de last laugh.", objectives = "Regroup with Zul'jarra, Zul'jan, and Lady Liadrin at the foot of Conquerer's Sanctum in Broken Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91009] = { id = 91009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durable Information Storage Container", description = "Adventurer, can you hear me? I've discovered a smaller titan device, the Durable Information Storage Container, which can fit on yer belt. I've deduced they'll be able tae play smaller titan discs, granting ye boons ye can use anywhere. \n\nEach of these devices need a jump start. If ye kick up enough dust in these delves it should generate a spark that the device will detect and collect. It should be enough tae power it for yer lifetime.", progress = "The overcharging is key.", completion = "Attach the device. Yes! The device is powered on. \n\nOkay... If I just start the initialization sequence... and it's up. There are already two discs inside. And the menu will list areas where other miniature titan discs can be found. I'm thinkin' I can improve the device, but I need time. Find me later and see.", objectives = "Complete a Delve to charge the device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91022] = { id = 91022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endeavor Reward" }
quests[91023] = { id = 91023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endeavor Reward" }
quests[91024] = { id = 91024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endeavor Reward" }
quests[91026] = { id = 91026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering an Upgrade", description = "Hello? Hello? You're back! Perfect!\n\nI was studying the titan console and gathering a bunch of new information from the overcharged areas including the faulty directives that were found. This might be the key to this unexpected behavior, but I'll need more time tae know for sure.\n\nReturn to the delves and we can check the results of the faulty directives, I can use the information to create an upgrade for yer belt!", progress = "Were ye successful?", completion = "Here, yes... With that information I can make some final tweaks. And adding this directive...\n\nAh! That should do it. If you insert this into yer durable information storage container, it should update the effectiveness of the device's, um... effects.", objectives = "Complete any Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91030] = { id = 91030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Titan Directives", description = "My calculations need a lot more data. I've got another upgrade card nearly finished, but I'm not sure if it will integrate properly.\n\nBut if ye go back into the delve spaces and defeat more of the enemies, I can see how they react. Based on their reactions, I can put the final touches on this upgrade for yer belt.", progress = "I can't wait to see the data!", completion = "Hmm, as I suspected. Yes... I need to adjust this here... done.\n\nThe good news is that this upgrade will nae make yer belt explode! I thought there was a small chance, but no longer. Yer data proved that I set the power too high. So... good thing I had ye do tha' extra check, right?", objectives = "Complete any Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91031] = { id = 91031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing it to the Limit", description = "I realized after ye left last time that I might have worried ye a wee bit with the whole exploding belt upgrade possibility. I'm sorry. I get a bit excited sometimes.\n\nI do think I can get even more power out o' the belt. At least a bit more. Safely of course! In yer data, I've seen that you've encountered many enemies as ye entered many delves. That's the key, return one more time for this last upgrade for yer belt.", progress = "I cannae wait to see if I was correct!", completion = "The data from that last excursion provided what I needed for another upgrade. But this is the last upgrade we can do for the belt, unless we want a major meltdown. Of course a meltdown would tell us a lot about the design...\n\nMa always said, \"Dagran! If yer gonna destroy ancient, irreplaceable artifacts, destroy yer own.\" So this is the last upgrade.\n\nHere is the last upgrade card. Thank ye for yer help. I hope we get a chance to experiment more in the future!", objectives = "Complete any Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91033] = { id = 91033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring 'Construct'ing", description = "Welcome back, adventurer. I have a simple request for ye. I need ye tae continue monitorin' these titan constructs. \n\nWe have seen them moving around Azeroth in different locations, but I've not yet figured out their end goal or what instructions they might have. Perhaps if ye can gather more information, an insight will present itself.", completion = "Their behavior seems mostly unchanged. This is very frustrating. Also if yer data is correct, it looks like they might be calmin' down. \n\nWe will have tae see if this observation is true. And here is some additional gear that we have collected. I hope it has served ye well over the course of our scientific endeavors!", objectives = "Complete an Overcharged Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91035] = { id = 91035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Construct De-Escalation", description = "Yer previous results showed a reduction in the overcharge present in the constructs. We must see if that was a one-off or if the reduction is escalatin'...\n\nHead back into these overcharged areas and test out the charge on the constructs, then report back.", completion = "Wow! Tha' drop off is huge. If this holds steady, these constructs could be gone soon! \n\nWe still don't know what prompted them to come out! What if we never know? I hope that they return.\n\nOh, no! I don't want them tae mess things up. I just hate tae leave this unsolved. \n\nAt least we will be more prepared if we do see them again. Thank ye for yer help, {name}. I've checked the numbers and yer belt should still work, even if the constructs do retreat. \n\nAnd one last box of supplies for yer help.", objectives = "Defeat 5 constructs and complete an Overcharged Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91038] = { id = 91038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellhunters Wanted", description = "<A scorch-marked missive has been nailed to this wall.>\n\nHELL COMES FOR YOU!\n\nNow that we have your attention, please be warned that shards of brimstone have entered this world. They are warm to the touch and should not, under any circumstances, be stabbed into your head, the head of anyone else, or any other vital organ of you or anyone near you.\n\nPlease bring any shards you find IMMEDIATELY to us in Dornogal.\n\nAnd if you see any tiny little minions carrying a bag of treasures, KILL THEM ON SIGHT.", completion = "We appreciate your interest in aiding us.\n\nShards of our timeline have made their way into your world. It is a place more grim and dark than your own, where some villains became heroes and some heroes never had the chance.\n\nHelp us locate these hellish fragments out of time and return them to their rightful place, and we will provide you with armors tempered by the fires of our world.\n\nAnd should you find any Treasure Goblins that lurk in your world, we implore you to slay the abominations.", objectives = "Bring the missive to Baranar in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91039] = { id = 91039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerin's Request", description = "{name},\n\nGeya'rah and Danath have arrived in Dornogal. They both seem upset about rising tensions in the Arathi Highlands. It sounds serious.\n\nCan you come to Dornogal? I believe your presence can help the situation.\n\nFaerin", completion = "{name}! Thank you for coming.", objectives = "Speak to Faerin Lothar in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91040] = { id = 91040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vexatious Vilebranch" }
quests[91041] = { id = 91041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91042] = { id = 91042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91044] = { id = 91044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger of the Void", description = "I did all I could to prevent this outcome. If you hadn't pushed him through the portal the unrestrained void energy would've collapsed the cave around us.\n\nHe was strong. In a way, I think that worked against him.\n\nMeet me back in Shan'dorah. I need to report to Umbric and let him know what happened here.", progress = "I could feel the void energies roiling from here, {class}. What exactly happened?", completion = "I sincerely hope that Adarus is well, and that he doesn't blame us. The ren'dorei have enough enemies as it is.\n\nI am excited that Leona has made a breakthrough. Though she never would have succeeded without your help.", objectives = "Reconvene with Magister Umbric and Leona back in Shan'dorah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91052] = { id = 91052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Overcharged Delves", description = "Something has caused hostile titan constructs to activate and enter various caverns and spaces around Khaz Algar. Venture to these locations and investigate and eliminate the threat they pose.", completion = "It is unnerving to not know what has forced these hostile titan units to surface. But due to your efforts their threat is at an end.", objectives = "Complete an Overcharged War Within Delve at any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91061] = { id = 91061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Chaos", description = "You may think this ironic, but our time is running short, {name}. Great forces threaten more than one world's future.\n\nNozdormu won't like it, but I must hasten our study with experimentation. I have isolated a fractured timeline for you to explore. But be warned--this realm is devoid of all hope. It is the only way I can truly prepare us for what is to come.\n\nI have established a research console by the fel monument behind you. Use it to enter this forbidden future so that we may learn the unknowable.", progress = "Have you seen the dark times that could have been?", completion = "You are braver than I thought, {name}.\n\nPlease continue to experiment. I will not let us enter dangerous futures unprepared.", objectives = "Explore the Heroic World Tier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91062] = { id = 91062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Bridges", description = "I make one last request of you before you return with Liadrin to Silvermoon, hash'ura.\n\nFind Zul'jan. None have seen him since returnin' to Amani'Zar.\n\nOn de way back here, I confronted him about takin' our soldiers to Broken Throne against my orders.\n\nPeople died dat shouldn't have. I asked him what he don't understand about dat.\n\nHe didn't argue. He was blank. His body was there, but his mind?\n\nSometimes he seeks peace in de sound of ocean waves.\n\nYou might find him on de Skybridge.", completion = "Glad I found you. Zul'jarra let me know you would be searching this area for Zul'jan, but this land is still so unfamiliar to me.\n\nIf you have found him and are finished enjoying the party, we should return to Silvermoon.", objectives = "Seek out Zul'jan upon the Skybridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91063] = { id = 91063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blooming Lattice", description = "You're that stranger I've been hearing about, aren't you? I'm Su'meera, apprentice painter to Ja'kul. You heard of him? No? Maybe his work hasn't made it to your lands. That makes sense, I guess.\n\nAnyhow, I heard you like helping people out. Well, a few important things went missing when Ja'kul was attacked and killed. I want them back.\n\nWill you meet me near Blooming Lattice?", completion = "Thanks for coming. I wasn't sure you would. Up the hill that way is Blooming Lattice--a settlement of rutaani who are quite vicious.\n\nTheir leaders killed Ja'kul, and took his things. I want them back!", objectives = "Meet Su'meera near Blooming Lattice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91065] = { id = 91065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purloining Petals", description = "A couple of days ago, a group of rutaani attacked and killed my mentor, Ja'kul. When they did, their stupid birds stole a few things from him. Those petals-for-brains will make off with anything shiny that isn't thorned down.\n\nWill you recover Ja'kul's things for me? I'm a painter, not a fighter. I wouldn't last very long in there on my own.", progress = "Those birds would steal your head if it wasn't attached to your shoulders. Especially if you were wearing a shiny hat or helm. Right off your shoulders!\n\n<She pauses for a moment as if picturing this, then turns slightly green and shudders.>", completion = "You did it! I knew they had these, those rotten weed-for-brains scavengers!\n\nI know it's silly to be upset about things like a favorite spoon, but they took Ja'kul's life. I won't let them take anything else from him.\n\nYou're the best, {name}.", objectives = "Recover stolen objects from Blooming Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91066] = { id = 91066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewmaster's Kitchen", description = "Good, you've brought the supplies. Now, we begin the feast. We'll need plenty of food to keep up our strength.\n\nThe menu's simple, but worthy: Barley Stew, Stone-baked Pretzels, and a strong brew to fuel the Horde!\n\nAre you prepared to learn?", progress = "Start the fire and get to work!", completion = "Hah! I can smell those pretzels from here. You've cooked up a feast fit to silence even the grumbling of dwarves!", objectives = "Follow the steps to cook Brewfest food and a delicious Brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91067] = { id = 91067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Grub", description = "Ah, you're here. Brewfest has begun-but we've got a problem. Can't have a proper feast without food, and some thieving hozen thought it'd be clever to snatch our grub.\n\nHere's what you'll do: track down those hozen and take back what's ours. You might find a few bags just lying around too-grab those. Once you've got the goods, toss them in the wagon behind me.", progress = "The feast won't come together without those ingredients!", completion = "You've done it! The cooks will be pleased.", objectives = "Collect Bags of Brewfest Ingredients and deposit them at the wagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91068] = { id = 91068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serving with Style", description = "You've proven your strength at cooking, now it's time to prove it on the floor! Brewfest isn't just about feastin-it's about bringing the revelry to every corner of the camp.\n\nYou'll be taking orders, hauling plates, and pouring ale like a true warrior of celebration.\n\nNow get out there and show them what real service looks like! Brewfest don't run on empty mugs!", progress = "Remember to serve with a smile!", completion = "I'd say you've earned yourself a break and a strong brew after all that work. But don't go getting soft on me! Brewfest isn't over, and there's still plenty of work to be done.", objectives = "Take the customer's order and serve the food to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91069] = { id = 91069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Tolbani", description = "Me and Tolbani had loaded de skiff with medicine, steel, and food to bring upriver to de forward camp.\n\nIt was meant to be a quiet run: no trouble, and no eyes on us.\n\nBut in de shallows, de murlocs came swarmin' out of de reeds all foam and teeth. Dey hit us hard--too fast to fight back proper. We tipped and lost de cargo. I barely made it to shore.\n\nTolbani didn't. I dragged his dart-riddled body here.\n\nDe murlocs must pay for what dey have done.", progress = "Bleed de mindless beasts. Make dem suffer for killin' Tolbani.", completion = "Do you hear dat?\n\nIt's quiet.\n\nDat is de sound of vengeance.", objectives = "Kill 12 murlocs in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91070] = { id = 91070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaim the Goods", description = "While I was limping back from de river, I spotted a few of de murlocs dragging our food bags through de mud. They weren't working together either--kept snapping at each other, trying to snatch de best pieces for themselves.\n\nI saw one of them stash a whole satchel behind a fallen tree. Another buried something under a pile of rocks. Greedy little monsters think they can steal from us and get away with it.", progress = "Yes, {class}?", completion = "Good. That's all of it.", objectives = "Find 6 stolen Food Provisions in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91071] = { id = 91071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menace of Atal'Abasi", description = "Our boat didn't ground on its own.\n\nWe were fightin' de murlocs, and then suddenly we were in de air.\n\nDats when I saw him--one dat wasn't like de rest. Bigger. Stronger. When he attacked, de other murlocs scattered.\n\nHe picked up our boat like it weighed nothin' and hurled it on de rocks. I've never seen a murloc do somethin' like that.\n\nWe're gonna keep losin' people and supplies if dat muscle-bound murloc is watchin' de river.", completion = "I saw de small ones run away in terror. Well done, {class}.", objectives = "Find and slay Mrruk the Musclefin in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91084] = { id = 91084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Shadows", description = "Though we've triumphed over Ruia and the Lightbloom for now, more remains to be done. The elders will want to convene regarding the Hara'ti's new place in the world, now that we have stepped out from the shadows of our past.\n\nOur reticence and fear will not vanish overnight. But this is an important first step.\n\nWe will be fine, {name}. Let Orweyna and I deal with the elders. When the time comes, the Hara'ti shall be at your side. For now, though, I'd imagine you have more pressing matters to attend to.", completion = "When Halduron burst into a war council shouting about hidden worlds and ancient warriors, I thought he had gone mad. But now that I've seen the haranir with my own eyes...\n\nWe are lucky to have them as potential allies. And lucky to have you, I'd say, in brokering that relationship.\n\nThere is more for us to do. But I've no doubt that the Hara'ti will prove vital allies to Silvermoon in the days to come.", objectives = "Return to Regent Lord Lor'themar Theron in the Sanctum of Light in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91085] = { id = 91085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Petal Bristles", description = "Ja'kul was out hunting petalwings when the rutaani came upon him and killed him. We use their feathers for some of our paintbrushes. They are especially useful in helping the young sprouts learn how to be more precise and delicate. \n\nWhile you're up there, will you bring me back some of their plumes?", progress = "Have you gathered the petalwing plumes I asked for? They're essential for the lessons of the younger haranir.", completion = "Thank you for bringing me these feathers! I will use one of them to paint a special memorial for Ja'kul. The rest will go to the children. \n\nI suppose it will fall to me now to teach them.", objectives = "Collect 8 Petalwing Plumes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91086] = { id = 91086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nipping the Buds", description = "The rutaani of Blooming Lattice were behind the attack on Ja'kul. They're led by a Prime Bloomwarden who's even more vicious. I hate them and they're all terrible!\n\nHow about you go prune the overgrowth and make the rest of us safer?", completion = "Is it done? Thanks. It won't bring Ja'kul back, but now they won't be hurting anyone else.", objectives = "Kill rutaani and the Prime Bloomwarden in Blooming Lattice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91087] = { id = 91087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reports Returned", description = "I will go to Silvermoon but... I will return here to advise Zul'jarra.\n\nI feel I let my past and my prejudices get in the way of my judgement regarding the Amani. You could say that being a hash'ura is a befitting atonement but... I feel drawn to stay, perhaps to help Zul'jarra in guiding her people back to the loa.\n\nI will go to Silvermoon with you to bear the report--and Lor'themar's reaction.\n\nIf we go now, we may return to... party.\n\n<A small smile cracks Liadrin's usually stoic face.>", completion = "<Lor'themar raises an eyebrow and frowns slightly. You can tell he is fighting back exasperation and anger.>\n\nThis is a... very unexpected turn of events. Yet still more will unfold in front of us, I'm sure.", objectives = "Report to Lor'themar Theron in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91088] = { id = 91088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind the Falls", description = "The scroll you brought back was left behind for me by my mentor, Ja'kul. I didn't even have a chance to read it before it was stolen away! \n\nJa'kul left directions in the scroll to a cave that's behind a waterfall in Blooming Lattice. I'm not sure what we'll find there, but I would really appreciate if you came along while I check it out. Will you meet me there?", completion = "This is incredible! I can't believe there's a whole cave back here. And Ja'kul left behind a vision stone for me.", objectives = "Meet Su'meera in the cave behind the waterfall in Blooming Lattice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91089] = { id = 91089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeating Ky'veza", description = "So she's here to collect a bounty, eh?\n\nDid nae one tell her it's rude to try and kill a Champion of Azeroth? Or a Bronzebeard, for that matter?", completion = "Whew! Good riddance.\n\nI cannae stand all tha skulking around and teleportin' about tha place.\n\nMight be time for a wee bit of vacation after all this excitement.", objectives = "Increase your item level to challenge Ky'veza in her tier 8 delve on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91090] = { id = 91090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pesky Pests", description = "Nearby creatures are suffering an infection of Light, and are being drawn to the Sunbath. Our guests find it disturbing. That is a problem, when one is trying to enjoy a tranquil escape from the world.\n\nI confess, having one run into your leg while you are swimming can be unnerving.\n\nPlease, dissuade the invading sungrubs from joining us, and take to the sky to chase off those persistent butterflies.", progress = "Are the insects giving you trouble?", completion = "That wasn't so bad, was it? \n\nVal does get a bit dramatic, but you performed wonderfully.", objectives = "Kill 10 Sungrubs and fly to chase away 10 Persistent Butterflies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91093] = { id = 91093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Just a Phase", description = "Untethered Space represents an ongoing danger to our people on K'aresh. It is infested with banished souls, broken technology, and monsters of all kinds.\n\nAid the K'aresh Trust and defeat our foes in Untethered Space. You may use the Phase Conduits to navigate between the remnants of K'aresh while phase diving.", progress = "I dream of a day when we K'areshi can roam these lands freely and without fear.", completion = "Your assistance is most appreciated, {race}. The Trust was wise in appointing you to aid our efforts.", objectives = "Complete activities while phase diving in Untethered Space on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91095] = { id = 91095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magister Sunbreaker (Normal)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "Hunt down Magister Sunbreaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91096] = { id = 91096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magistrix Emberlash (Normal)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "Hunt down Magistrix Emberlash and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91097] = { id = 91097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Senior Tinker Ozwold (Normal)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "Hunt down Senior Tinker Ozwold and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91098] = { id = 91098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: L-N-0R the Recycler (Normal)", objectives = "Hunt down L-N-0R the Recycler and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91099] = { id = 91099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Mordril Shadowfell (Normal)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n\nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "Hunt down Mordril Shadowfell and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91100] = { id = 91100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Deliah Gloomsong (Normal)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "Hunt down Deliah Gloomsong and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91101] = { id = 91101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Phaseblade Talasha (Normal)", description = "Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me.\n\nMy scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.", objectives = "Hunt down Phaseblade Talasha and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91102] = { id = 91102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Nexus-Edge Hadim (Normal)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "Hunt down Nexus-Edge Hadim and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91103] = { id = 91103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Jo'zolo the Breaker (Normal)", description = "Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! \n\nKill him. Feed his anguish to the defenses of our beloved city.", objectives = "Hunt down Jo'zolo the Breaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91104] = { id = 91104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Zadu, Fist of Nalorakk (Normal)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. \n \nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "Hunt down Zadu, Fist of Nalorakk, and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91105] = { id = 91105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: The Talon of Jan'alai (Normal)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "Hunt down The Talon of Jan'alai and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91106] = { id = 91106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: The Wing of Akil'zon (Normal)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "Hunt down The Wing of Akil'zon and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91107] = { id = 91107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Ranger Swiftglade (Normal)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "Hunt down Ranger Swiftglade and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91108] = { id = 91108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lieutenant Blazewing (Normal)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "Hunt down Lieutenant Blazewing and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91109] = { id = 91109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Petyoll the Razorleaf (Normal)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "Hunt down Petyoll the Razorleaf and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91110] = { id = 91110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lamyne of the Undercroft (Normal)", objectives = "Hunt down Lamyne of the Undercroft and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91111] = { id = 91111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: High Vindicator Vureem (Normal)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "Hunt down High Vindicator Vureem and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91112] = { id = 91112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Crusader Luxia Maxwell (Normal)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "Hunt down Crusader Luxia Maxwell and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91113] = { id = 91113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Praetor Singularis (Normal)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "Hunt down Praetor Singularis and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91114] = { id = 91114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Consul Nebulor (Normal)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic.\n  \nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "Hunt down Consul Nebulor and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91115] = { id = 91115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Executor Kaenius (Normal)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "Hunt down Executor Kaenius and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91116] = { id = 91116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Imperator Enigmalia (Normal)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "Hunt down Imperator Enigmalia and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91117] = { id = 91117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Knight-Errant Bloodshatter (Normal)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n \nHe is starting to become a liability. \n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "Hunt down Knight-Errant Bloodshatter and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91118] = { id = 91118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Vylenna the Defector (Normal)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n\nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "Hunt down Vylenna the Defector and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91119] = { id = 91119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lost Theldrin (Normal)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "Hunt down Lost Theldrin and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91120] = { id = 91120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Neydra the Starving (Normal)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slack her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "Hunt down Neydra the Starving and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91121] = { id = 91121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thornspeaker Edgath (Normal)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "Hunt down Thornspeaker Edgath and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91122] = { id = 91122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thorn-Witch Liset (Normal)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "Hunt down Thorn-Witch Liset and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91123] = { id = 91123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Grothoz, the Burning Shadow (Normal)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "Hunt down Grothoz, the Burning Shadow and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91124] = { id = 91124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Dengzag, the Darkened Blaze (Normal)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "Hunt down Dengzag, the Darkened Blaze and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91136] = { id = 91136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories in Stone", description = "Ja'kul was killed before he could finish my training, but I would recognize his work anywhere! He must have painted this vision stone for me!\n\nThe rutaani will catch on pretty soon that we're up here, and I won't be able to defend myself. Will you keep watch while I journey into the memory he left me?", completion = "Thank you so much, {name}. You gave me a way to say goodbye to my mentor. Now that I have seen what he wanted me to, I can continue my training.\n\nIt means so much that Ja'kul left this here for me. I miss him, but I will honor his memory.", objectives = "Defend Su'meera while she vision walks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91137] = { id = 91137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Light", description = "It seems some of our more adventurous guests have not returned from their hike. Val said he saw a rutaani skulking about earlier, but I was certain he was just trying to add some drama to our day.\n\nThe Lightbloom infiltrated the Sanctum to the north and has been spilling residual issues our way.\n\nOur guests are here to escape the troubles of the world... This all could become a bit too real for them.\n\nIf you'll take care of that situation, I'll make sure Val keeps the guests distracted.", progress = "Did they make it back?", completion = "Tormenting our guests was a step too far.\n\nShe encroached on the sunbath and has paid the price for her actions.\n\nThank you, new friend of the Solaar family!", objectives = "Kill Liya Waterbloom and send the hikers home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91138] = { id = 91138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I am the Creator and Destroyer", description = "Such a small thing, really. And devoid of any of the power T'uure once nurtured. But a relic of inestimable value nonetheless.\n\nDid you know, {class}, that to T'uure, the dark and the light were inseparable aspects of a greater truth?\n\nWhat creates, has the power to destroy in equal measure. Demonstrate this lesson and you will reach a new understanding of yourself, and of the great Naaru whose sacrifice was able to halt the annihilation of an entire planet.", completion = "Ah yes. I can sense the change in you. The growth that comes with meting out death in one hand, while nuturing life in the other.\n\nPerhaps this small token will serve as a reminder of T'uure and his role in Dimensius' ultimate fate.", objectives = "Demonstrate your mastery over life and death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91140] = { id = 91140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Piece of the Past", description = "<This crystalline fragment has lost any luster it once had. Now finally extricated from Dimensius's dread form and in the hands of the devout, a brief glimmer revives in its depths.\n\nPerhaps someone in Tazavesh will know more.>", progress = "What is this? Ah, I see now. You were right to come to me.", completion = "A fragment of the lost naaru T'uure? And lodged in the form of Dimensius?\n\nNow this is something I never thought I'd see.", objectives = "Show the fragment to Om'en in Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91142] = { id = 91142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard for the Trusted", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91143] = { id = 91143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Crests", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91145] = { id = 91145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquered Heroes", description = "A domanaar was harrying our back lines. It was... different than the other void beasts--like it was playing rather than fighting. My partner, Callum, led a squad to hunt it down. They never came back.\n\nCallum's an Arathi through and through. He wouldn't fall here--I know it.\n\nCommander Lightblood refused to send a search party. He said there's a difference between personal and important. Well, the Vanguard can have their war, but I'm going after Cal. I know the route he took, but I can't search alone.", completion = "Imperia's beasts swarmed me. I lost track of them.\n\nI shouldn't have left you behind, but seeing that monster control Callum... I'm not losing him. Not while I still breathe.", objectives = "Find Callum Ashvow's squad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91146] = { id = 91146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Light", completion = "She's hurting him, throwing him into fight after fight. We don't have time to search this whole blasted plain.\n\nI can't concentrate. The Void magic here is too chaotic and volatile.", objectives = "Find traces of Callum's Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91147] = { id = 91147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Her Strings", description = "Revik, Riandron, Danna... that domanaar made them kill each other. The creatures here are bound with the same shadowgrafts: the same twisted magic.\n\nIf this is how Imperia controls her victims, we have to find a way to remove it.\n\nRestrain the beasts and I'll attempt to break their bonds. If it's forged by the Void, the Light must be able to overcome it.", completion = "Removing the Shadowgrafts kills them... What good is the Light if it can't save one man?", objectives = "Subdue creatures while Anais removes their Shadowgrafts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91148] = { id = 91148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strung Along", description = "When the Light called, it called both of us. Why? So Callum could die on some void-scarred rock?\n\nI can't think here. All I can picture is Callum bleeding out. Come, we'll return to camp. With his belongings, I should be able to find him. \n\nThen... I don't know. If we can't break the shadowgrafts, we'll subdue him and drag him back to Silvermoon if we must. I'm not losing him.", completion = "I had him. One spear thrust and I could have ended it... but he's still Cal--even with that monster controlling him.\n\n<Anais clutches at ragged cut in her side. Blood and foul Void magic flow from the wound in equal measure.>\n\nLook what chasing after him again got me.", objectives = "Help Knight Anais find and subdue Callum Ashvow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91149] = { id = 91149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bury Me Not", description = "I knew we'd never grow old together, but I thought we'd have more time.\n\n<Anais coughs, blood pooling beneath her. Flecks of the Void shimmer in the spreading crimson.>\n\nDon't worry. I'm not afraid. I promised myself I wouldn't go home without him... wouldn't spend a night in an empty bed. I'm just keeping that promise.\n\nDon't let her have him. Take his tinder box. You'll know what to do.", progress = "My parents always said falling in love with a human would end in heartbreak.\n\n<She doesn't lift her head.>\n\nThere's never enough time, is there?", completion = "I felt it. When you--when he--thank you. Sorry. Getting hard to think.\n\n<She accepts the tinder box and holds it to her chest. Her eyes seem to focus on something you can't see.>\n\nCal...? I'm so tired. Let's go home.\n\n<Anais slumps over, her hand falling away from the wound at her side. She is at peace.>", objectives = "Take Callum's Tinder Box and defeat Imperia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91173] = { id = 91173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flame Burns Eternal", description = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades.\n\nCan we count on your continued support in the battles ahead?", progress = "Ready yourself soldier, the battle is still to come.", completion = "You've bought us a moment of peace.\n\nRest well, but always keep your blade sharp.", objectives = "Complete the Nightfall scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91193] = { id = 91193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Capstone 1 - Unlock" }
quests[91197] = { id = 91197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting Remains", progress = "The domanaar need void-tainted remains to fuel their war effort. Scavenge the area or slay fellow adventurers across Slayer's Rise to obtain this resource.", completion = "Thank you for your contributions.", objectives = "Collect 50 Void-Tainted Remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91203] = { id = 91203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Capstone 2 - Unlock" }
quests[91205] = { id = 91205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ultra Prime Deluxe Turbo-Boost: Powerhouse Challenges", description = "<Undermine has a problem. Here's what we need. An established group, or just a bunch a ya really, ready to help out our pals in Undermine. Help clear out the worst of the competition, and we'll make it worth your time.\n\nComplete the task, and collect a special reward from Consultant Wrexxle outside of the the Dornogal Treasury. Limited time offer. Some restrictions will apply.>", progress = "Yous looks out for us, and we return the favor. Right?", completion = "Thanks, pal. Undermine is a mess right now. We'll take all the help we can get.\n\nAnd hey, a deal's a deal. Here's what we owe.\n\nWe call this the jackpot reward for first time help. Check back again for more work!", objectives = "Defeat any four bosses within The Liberation of Undermine raid on Looking For Raid difficulty or higher, or complete any four Mythic Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91206] = { id = 91206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa Disturbance", description = "Now dat we are tryin' to contact all de loa, my mind turns to Kulzi, de loa of medicine--and the madness that surrounds his shrine.\n\nHis loa speaker, Sij'ta, was a good friend. He healed many war parties of their injuries. But somethin' happened at Kulzi's shrine, and it is full of angry spirits.\n\nDey attack anybody dat tries to get through to dem, and de loa is silent.\n\nPerhaps you can finally reach out to de loa and find his speaker!", completion = "What do you mean, you don't have de medicine? I sent you for it ages ago!\n\nWe must help him... even if de loa won't!", objectives = "Find Loa Speaker Sij'ta at the Shrine of Kulzi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91207] = { id = 91207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Apex Predator" }
quests[91210] = { id = 91210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magister Sunbreaker (Hard)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "Hunt down Magister Sunbreaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91211] = { id = 91211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magister Sunbreaker (Nightmare)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "Hunt down Magister Sunbreaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91212] = { id = 91212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magistrix Emberlash (Hard)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "Hunt down Magistrix Emberlash and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91213] = { id = 91213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Magistrix Emberlash (Nightmare)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "Hunt down Magistrix Emberlash and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91214] = { id = 91214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Senior Tinker Ozwold (Hard)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "Hunt down Senior Tinker Ozwold and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91215] = { id = 91215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Senior Tinker Ozwold (Nightmare)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "Hunt down Senior Tinker Ozwold and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
