quests[91228] = { id = 91228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Zadu, Fist of Nalorakk (Hard)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. \n \nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "Hunt down Zadu, Fist of Nalorakk, and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91229] = { id = 91229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Zadu, Fist of Nalorakk (Nightmare)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with.\n\nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "Hunt down Zadu, Fist of Nalorakk, and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91230] = { id = 91230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: The Talon of Jan'alai (Hard)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "Hunt down The Talon of Jan'alai and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91231] = { id = 91231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: The Talon of Jan'alai (Nightmare)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "Hunt down The Talon of Jan'alai and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91232] = { id = 91232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: The Wing of Akil'zon (Hard)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "Hunt down The Wing of Akil'zon and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91233] = { id = 91233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: The Wing of Akil'zon (Nightmare)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "Hunt down The Wing of Akil'zon and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91234] = { id = 91234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Ranger Swiftglade (Hard)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "Hunt down Ranger Swiftglade and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91235] = { id = 91235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Ranger Swiftglade (Nightmare)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "Hunt down Ranger Swiftglade and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91236] = { id = 91236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lieutenant Blazewing (Hard)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "Hunt down Lieutenant Blazewing and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91237] = { id = 91237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lieutenant Blazewing (Nightmare)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "Hunt down Lieutenant Blazewing and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91238] = { id = 91238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Petyoll the Razorleaf (Hard)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "Hunt down Petyoll the Razorleaf and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91239] = { id = 91239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Petyoll the Razorleaf (Nightmare)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "Hunt down Petyoll the Razorleaf and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91240] = { id = 91240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lamyne of the Undercroft (Hard)", objectives = "Hunt down Lamyne of the Undercroft and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91241] = { id = 91241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lamyne of the Undercroft (Nightmare)", objectives = "Hunt down Lamyne of the Undercroft and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91242] = { id = 91242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: High Vindicator Vureem (Hard)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "Hunt down High Vindicator Vureem and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91243] = { id = 91243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Crusader Luxia Maxwell (Hard)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "Hunt down Crusader Luxia Maxwell and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91244] = { id = 91244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Praetor Singularis (Hard)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "Hunt down Praetor Singularis and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91245] = { id = 91245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Consul Nebulor (Hard)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic. \n \nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "Hunt down Consul Nebulor and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91246] = { id = 91246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Executor Kaenius (Hard)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "Hunt down Executor Kaenius and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91247] = { id = 91247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Imperator Enigmalia (Hard)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "Hunt down Imperator Enigmalia and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91248] = { id = 91248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Knight-Errant Bloodshatter (Hard)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n\nHe is starting to become a liability.\n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "Hunt down Knight-Errant Bloodshatter and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91249] = { id = 91249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Vylenna the Defector (Hard)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n \nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "Hunt down Vylenna the Defector and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91250] = { id = 91250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lost Theldrin (Hard)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "Hunt down Lost Theldrin and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91251] = { id = 91251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Neydra the Starving (Hard)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slack her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "Hunt down Neydra the Starving and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91252] = { id = 91252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thornspeaker Edgath (Hard)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "Hunt down Thornspeaker Edgath and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91253] = { id = 91253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thorn-Witch Liset (Hard)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "Hunt down Thorn-Witch Liset and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91254] = { id = 91254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Grothoz, the Burning Shadow (Hard)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "Hunt down Grothoz, the Burning Shadow and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91255] = { id = 91255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Dengzag, the Darkened Blaze (Hard)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "Hunt down Dengzag, the Darkened Blaze and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91256] = { id = 91256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: High Vindicator Vureem (Nightmare)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "Hunt down High Vindicator Vureem and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91257] = { id = 91257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Crusader Luxia Maxwell (Nightmare)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "Hunt down Crusader Luxia Maxwell and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91258] = { id = 91258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Praetor Singularis (Nightmare)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "Hunt down Praetor Singularis and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91259] = { id = 91259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Consul Nebulor (Nightmare)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic.\n\nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "Hunt down Consul Nebulor and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91260] = { id = 91260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Executor Kaenius (Nightmare)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "Hunt down Executor Kaenius and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91261] = { id = 91261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Imperator Enigmalia (Nightmare)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "Hunt down Imperator Enigmalia and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91262] = { id = 91262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Knight-Errant Bloodshatter (Nightmare)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n \nHe is starting to become a liability. \n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "Hunt down Knight-Errant Bloodshatter and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91263] = { id = 91263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Vylenna the Defector (Nightmare)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n\nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "Hunt down Vylenna the Defector and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91264] = { id = 91264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Lost Theldrin (Nightmare)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "Hunt down Lost Theldrin and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91265] = { id = 91265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Neydra the Starving (Nightmare)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slack her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "Hunt down Neydra the Starving and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91266] = { id = 91266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thornspeaker Edgath (Nightmare)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "Hunt down Thornspeaker Edgath and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91267] = { id = 91267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Thorn-Witch Liset (Nightmare)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "Hunt down Thorn-Witch Liset and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91268] = { id = 91268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Grothoz, the Burning Shadow (Nightmare)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "Hunt down Grothoz, the Burning Shadow and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91269] = { id = 91269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Dengzag, the Darkened Blaze (Nightmare)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "Hunt down Dengzag, the Darkened Blaze and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91270] = { id = 91270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Most Important Thing", description = "We will be strong for the Pit!\n\nBut Boletus right. Another thing needed. Must have great name.\n\nBest teams all have good name. Fungus Force. Spore Storm. Cap Clash. And champions, Glow Guard!\n\nAll good names.\n\nWe need amazing name. Best name. So will be best team.\n\nYou help choose?", progress = "Find best name?", completion = "Fungal Fell...owship, ok. Now we ready.\n\nWill run into pit together, shout the Fungal Fello...sip, eh...\n\nCrowd will cheer, then will be new champions!", objectives = "Speak to each of your teammates to choose a name.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91271] = { id = 91271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fish!", description = "There is a deliciously delectable dish that I am dying to share with my guests. We start with just the right fish, then chop it up, drop it in a blend of citrus and our special savory seasonings, and let it bask in the glorious flavors.\n\nIn the shake of a tail feather, it becomes a magical delight for the senses!\n\nWe are the talk of the town, you know. Could you please procure for us the perfect fish?", progress = "I have a great feeling about this one!", completion = "Excellent work, {name}! You have procured a perfectly, pleasingly, plumply proportioned pescatarian prize!\n\nJoyous day!", objectives = "Catch the best fish for the dish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91274] = { id = 91274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Severing the Void", description = "The High Exarch has formed an impressive defensive line. It will hold the Devouring Host's current numbers. But I can see void pylons behind the lines. Those will call forth more Devouring Host and overwhelm the Vanguard of Light.\n\nTheir power is too dangerous for us to destroy directly, but if we can re-activate the sentinels that fell in the initial assault, they could destroy the pylons for us.", progress = "We need to activate all the sentinels if we want to destroy the void pylons.", completion = "With those void pylons destroyed, the Devouring Host has weakened. We may have a chance of winning this.", objectives = "Activate 5 Quel'Danas Sentinels to destroy the Void Pylons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91277] = { id = 91277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Preferential Killing", description = "The anguish you've brought me has been... impeccable. As potent and complex as a finely aged wine.\n\nNormally, scrying the rough whereabouts of our targets takes me time and power. But using these overflowing stores of anguish, I can find anyone you desire to slaughter.\n\nYou have done well, my champion. You deserve to reap this bounty. Tell me what you want.", sourceObjective = "Speak to Astalor to select a customized Prey target, zone, and difficulty.", progress = "Consider your choices with relish.\n\nI know I do.", completion = "Hunt well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[91281] = { id = 91281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight", description = "Locate one of the images of Lady Liadrin that have appeared across Azeroth.", completion = "I am glad you came, {name}. We need your help urgently.", objectives = "Travel to the nearest Image of Lady Liadrin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91283] = { id = 91283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greedy Emissary" }
quests[91284] = { id = 91284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Path Not Yet Chosen", description = "I'm trying to figure out what career path to follow, but I keep second-guessing myself. The Farstriders, the Blood Knights, the Magisters... they all seem so incredible that I can't decide.\n\nI was hoping if I spoke to each and earned a recommendation, I might finally understand where I'm meant to be. Would you help me?", progress = "I really hope I find where I belong...", completion = "Wow... I can't believe I actually got all three recommendations. They all said such kind things, but now I feel even more torn than before!\n\nDo you think... perhaps you could help me choose?", objectives = "Collect Recommendations from the Farstrider, Blood Knight, and Magister trainers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91288] = { id = 91288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of the Hunt", description = "So, you want a Farstrider recommendation? We don't hand those out like festival ribbons.\n\nIf you want to earn it, then you'll need to do what every other recruit does. Bring me lynx pelts, clean and proper.\n\nNo shortcuts, no excuses. Let's see if you've got the spine for it.", progress = "Have you gotten those pelts yet or are you quitting already?", completion = "Well now, look at that. Clean cuts, no mess... maybe the kid's got more fire than I thought.\n\nHere, take this recommendation. Tell them a Farstrider never forgets who earns their place--and to keep their aim sharp. We'll be watching.", objectives = "Gather 8 Invasive Lynx Pelts in the Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91291] = { id = 91291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Blood", description = "Ah, you seek a Blood Knight's recommendation, do you? In that case, you'll need to prove your worth... against me. \n\nOnly those with true strength and honor may join our ranks! Prepare yourself. This won't be a simple challenge, but if you can best me, I'll gladly offer my recommendation!", progress = "Well, what do you think?", completion = "Impressive! You've got more in you than I expected.\n\nYou've proven your strength, honor, and determination--qualities every Blood Knight must possess.\n\nTake this recommendation and wear it with pride. The order is always looking for those who are worthy.", objectives = "Defeat Jesthenis Sunstriker in the Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91292] = { id = 91292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of the Arcane", description = "Ah, you seek a recommendation from a Magister, do you? Very well... but first, you must prove your understanding of the arcane.\n\nGo to the nearby crystals we have for training, extract their energy, and channel it into this staff. Show me that you can harness the arcane, and I will see you worthy of my recommendation.\n\nShould you fail, don't bother returning. My time is too valuable for such trivial matters.", progress = "Well? Is the staff charged, or are you wasting both our lives?", completion = "Hmm, it seems you have a bit more talent than I anticipated.\n\nThis staff is properly charged. Well done, though I'm sure you barely broke a sweat.\n\nTake this recommendation, and remember--the arcane demands respect, not just power.", objectives = "Charge the Arcane Transfer Staff 4 times in Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91301] = { id = 91301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Train Your Protege", description = "I did everything they asked--the trials, the lessons--and they all said I did well... but I still don't know where I truly belong.\n\nEach path felt right in its own way, and now my heart feels pulled in three directions.\n\nPlease... could you help me decide?", completion = "Ah... so the boy has chosen at last. He has heart--too much perhaps.\n\nYes. This will be recorded and honored. You've done more than deliver a message--you've helped shape a life. Thank you.", objectives = "Turn in the chosen recommendation to Instructor Thalendir in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91302] = { id = 91302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abundance: Abundant Grove" }
quests[91314] = { id = 91314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untethered Potential", description = "{class}--I heard you have explored Untethered Space? That place is soaked with pristine void energy. I would like to explore it myself, but the last who have ventured into were consumed by the Void.\n\nI need help with my research. There are Phase-Lost creatures in the Voidscar Cavern that I could use to examine their essence. If you could collect that for me, I would be grateful. \n\nGo carefully.", progress = "Were you able to collect the Phase-Altered essence?", completion = "This will provide a lot to forward my research on Untethered Space. I thank you.\n\nI can't imagine what discoveries we can begin to unravel about K'aresh.", objectives = "Collect 5 Phase-Altered essence in Untethered Space.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91328] = { id = 91328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Ingredients", description = "Our gregarious guests have partaken so much from our stores that we are running dangerously low of our special Solaarian sintalia.\n\nThe rich taste of belanise, with its intoxicating scent, contrasts perfectly with the sharp tartness of the local berries. Carefully prepared then soaked in our special blend of spirits, then served--it's to die for!\n\nJust between us, if the berries are not handled just right, the infusion can be quite deadly. Otherwise... delicious, invigorating, purifying, glorious!", progress = "Are you gathering carefully?", completion = "Magic! Perfection! You could not be more skilled if I had wished you into existence.\n\nThat is an interesting thought. Could I have?", objectives = "Collect 6 Belanise Blossoms and 5 Sinara Berries for the Solaarian Sintalia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91339] = { id = 91339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smothered in the Crib", description = "I summoned my first imp in a dirty, haze-filled lounge beneath Murder Row after a dozen failed attempts. Each time, I reached further for what made so-called greater powers submit to mortals. I finally managed it after wetting my hands with the hot blood of a young rabbit. Bloodthistle never satisfied me again.\n\nI have matured my technique since then. Seek the whelps of these beasts. Siphon their energy into my reliquary of darkness. From their sacrifice, we will draw the power to defeat Kalgorg.", completion = "This too is the natural order of things.", objectives = "Drain 9 juvenile wildlife with the Reliquary of Darkness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91340] = { id = 91340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Violence's Sake", description = "Like many warlocks, I bind my demons with terms of a contract. I should have realized the Void and violence of this world could affect the rules I took for granted. Kalgorg used that power to break its bindings and end our arrangement. \n\nWhen we confront Kalgorg, the scent of blood and violence must be upon us. Slay the beasts you find to demonstrate to Kalgorg we are willing to do the same to it. Control over the Void is found and lost within the blink of an eye.", completion = "<Lucia looks you over and then rewards you with a cruel smile.>\n\nSplendid. You are as capable as you look.", objectives = "Kill wildlife on the surface of the Den of Predaxas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91341] = { id = 91341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlimited", description = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you.\n\nKalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain, but we must proceed and claim the power within. Fill the reliquary to the brim. \n\nI know not what to expect from my voidwalker. We will need all the power we can manage.", progress = "The trail of carnage it left behind... I'm almost proud.", completion = "Kalgorg waits before us. Now we spend the power you've been collecting reclaim it.", objectives = "Gather Void Power within the Lair of Predaxas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91342] = { id = 91342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You Want It Done Right", description = "With all the problems facing Eversong, the Farstriders have their hands full!\n\nI'm a capable arcanist. I've always admired the Farstriders--why not lend my talents to their cause? They do so much work by hand, when a bit of magic would allow them so much more time for adventuring!\n\nAlas, my enchanted broom idea has not quite gone as I'd hoped. They're so ornery, they end up attacking the recruits instead of cleaning!\n\nPerhaps this is a problem for elbow grease after all.", progress = "Captain Dawnrunner warned me about trying to solve all my problems with magic... Clearly I have much yet to learn.", completion = "The sweeping will still need to get done, but at least now no one will be attacked.", objectives = "Slay 8 Ornery Sweepers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91343] = { id = 91343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambition's Reward", description = "You have filled the reliquary with power I can draw on. Now, we reap the reward of our preparations.\n\nKalgorg waits just ahead, draining the beast that once made this cave its lair. Weaken Kalgorg, and I will bind it as I first did years ago.", completion = "Kalgorg consumed much of the Void energy within that cave, which means its influence is less likely to overwhelm my kin. I suppose some good was done.\n\nI must pay Kalgorg the slightest compliment. Were I a subdued void beast, I'd also try to escape. For that, it has my respect.\n\n<Lucia turns to Kalgorg with a sharp smile.>", objectives = "Subdue Kalgorg the Unshackled.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91345] = { id = 91345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the North Tower", description = "Ranger Valsarin is a chef at Farstrider Hold. He's decent in a kitchen, but his passion is field cooking.\n\nThere was a time when you could wander any path in Eversong and find the ingredients for a good meal. A Farstrider's dream! With enough hard work, we can help the forest recover, and it starts with rehabilitating the soil.\n\nMeet Valsarin at the North Tower and he can tell you more.", completion = "Hope you like getting your hands dirty.", objectives = "Meet Ranger Valsarin at the North Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91346] = { id = 91346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplicants to the Goddess", description = "We have long tended to the roots with the help of the creatures who live and grow here. Think of it as a symbiotic relationship from which we, the creatures, and the roots all benefit. That said, my partner Riverscale isn't contributing very much lately!\n\nPlease help me find a way to motivate him again.\n\nFirst, you must cleanse off the essence of the outside. Cleanse yourself in the waters of Har'kuai.", completion = "This may seem inconsequential, but it's all a part of the process.", objectives = "Cleanse yourself in the Waters of Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91347] = { id = 91347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strider Stampede", description = "It's hard to believe this used to be the Dead Scar.\n\nUp here, close to the city, the land has almost completely recovered. Which is good, because we've got a lot of mouths to feed.\n\nHawkstriders are the perfect helpers for preparing the soil. Their tough claws can easily spread seeds and squash bugs!\n\nMeet me down in the Tranquil Repose and I'll saddle one up for you.", progress = "Nothing like planting seeds.", completion = "I don't know what to make of those big blooms... but whatever we're doing, the land seems pleased.", objectives = "Mount up the Saddled Hawkstrider and prepare the Tranquil Repose for gardening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91348] = { id = 91348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See a Mana 'bout a Wyrm", description = "Mana wyrms may not be as glamorous as lynxes or hawkstriders, but they're crucial to keeping magic flowing through the forest.\n\nThey congregate on the ley lines to molt, but sometimes they get a little agitated. And we have to help them out! Aggressively!\n\nI've set up some ley channels to get things started. Find wyrms that look like they could use a little help, and beat them up until they shed their arcane carapace. Don't worry--all that mana returns to the forest eventually!", progress = "Don't worry! They bounce right back.", completion = "Another successful molt... We'll be out here in a few weeks to do it all again!", objectives = "Aggressively assist 8 Agitated Wyrms with their molting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91349] = { id = 91349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Part of the Woods", description = "Much of the forest has recovered, but to the south... Everything that Eversong has faced--the Scourge, the fel, and now the Twilight's Blade--all that magic leeches into the soil. It builds up in the creatures until they're completely overwhelmed...\n\nMy instruments can detect corruption in these animals. We can cull the ones that are too far gone and save the ones that aren't. It isn't fun... but it's for the good of Eversong!", progress = "It's hard work, but it will bring peace eventually.", completion = "These poor cubs... They survived only by the grace of that strange magic!\n\nI know better than to believe in the old tales... but what else could it be?", objectives = "Test 8 creatures for corruption, and deal with the consequences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91350] = { id = 91350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Real Assignment", description = "Captain Dawnrunner was supposed to check on the Enclave and then meet us here. She's as capable a ranger as any! It's a bad sign if she's been detained.\n\nFarstrider Enclave is usually where they do wilderness training. With all the trouble however, everyone's been dispatched elsewhere. She could be up there alone, in serious danger!\n\nThere's no time to lose. I'm going to save my Captain and prove myself as a Farstrider!", completion = "This is what happens when there's no one around to sweep up!\n\nEveryone wants to adventure, but no one wants to sweep.", objectives = "Find Captain Dawnrunner at Farstrider Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91359] = { id = 91359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Lashers B Gone", description = "We are blessed to live in Harandar, but this is also our responsibility. The roots of the World Trees wind through these lands. We tend them, and they thrive. That is why it is so important for Riverscale to be back on duty.\n\nWe need to keep these grounds clear of these fungal lashers before they leach off the roots. As a plus, Riverscale really loves lasher fronds. Can you find and bring some back for him?", progress = "It's important that we keep the lashers from sapping important nutrients from the World Tree.\n\n...and I like spoiling my obstinate little boy.", completion = "I wish that I didn't have the laziest helper in the history of helpers, but such is life!\n\nIf his favorite treats won't get him up, nothing will.", objectives = "Collect 6 Harmonious Fronds in the outskirts of Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91360] = { id = 91360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weeding Out the Unwanted", description = "The roots of the World Trees are infused with both nutrients and the magic of Harandar. As the large vessels that they are, they will draw to them unwanted fauna and flora. Some of them are harmless, but we want to keep the roots clear.\n\nHaranir can often be allergic to the green weeds that flourish beside the roots of the World Trees. If you rip them out by the root, you would be saving us a lot of time--and hives!", completion = "You're a weed-pulling, no-rash juggernaut!", objectives = "Pull 8 Allergenic Weeds in the outskirts of Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91361] = { id = 91361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back on Duty?", description = "Finally! I knew the little guy could do it.\n\nNo, that is a bald-faced lie. If this grovecrawler could somehow find a way back into his cocoon, he would already be there.\n\n<Cyenna sighs.>\n\nHis second favorite treat is the potatoad. If that doesn't work, his third favorite treat is the petalwing. That should get him back onto his mite-hunting duties.\n\n...I have the backbone of a wet frond.", completion = "I knew you could do it, Riverscale! Who's a good grovecrawler? Who's the best crawler of them all?\n\nWho's a big strong grovecrawler who knows how to teach strangers how to care for World Trees?\n\n<Cyenna looks up at you.>\n\nYou knocked him out of his laziness, {name}. I can't thank you enough for your help.", objectives = "Help Riverscale gain his confidence by killing 8 Potatoads and Petalwings by the outskirts of Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91363] = { id = 91363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvest of Darkness", description = "You... make yourself useful.\n\nAs a master of terrible beasts, it is my job to mold these hatchlings into dreaded beasts. I pit them against each other and they grow ever more violent.\n\nBut the elves here insist that I will yield better results with just a bit of... tender loving care. Let us put this to the test.\n\nThis runt is Fidoficus. You will show him tenderness and affection, and then we will see how ferocious he becomes.\n\nCollect some delicious dietary treats for him and return to me.", progress = "These ingredients will make for a highly nutritious and equally delectable meal.", completion = "Fidoficus will be renowned for his ferocity.\n\nI can see the violence growing in him.\n\nOne day, he will be a worthy pet for a domanaar such as myself.", objectives = "Collect 10 Void-Infused Morsels and 6 Glaring Glowcaps outside of the Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91375] = { id = 91375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silence at Fungara Village", description = "Fungara Village has been silent for some time now.\n\nWe've largely been occupied with the Lightbloom and the threat it presents, so we haven't had time to check in on the fungarians to the east. Usually, they are rowdy yet manageable... but it's rare that they go completely silent.\n\nI am going to investigate. If you wish to prove yourself an ally, you would do well to join me.", completion = "Normally, I would refuse the intervention of an outsider without a second thought... but given the situation, perhaps you can be of some help.", objectives = "Seek Ghikal outside of Fungara Village in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91376] = { id = 91376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Monsters", description = "When I sent a request for aid from Har'alnor, I did not expect them to send me an outsider. No matter.\n\nThe denizens of Fungara Village have gone quiet. Normally, I would be thrilled: they're horribly screechy. But the way they are shambling about... it is like they have forgotten that they yet live.\n\n<Ghikal shudders.>\n\nI tried to get close, but they attacked me on sight.\n\nI will need samples of their flesh. Go and bring them to me, so I can see what has happened here.", progress = "I do not know what is going on, but to err on the side of caution... do not let them bite you, hrm? Whatever plagues them may be infectious.", completion = "Goddess forfend. This is not fungarian flesh at all.\n\nWhat ARE they?", objectives = "Collect 10 samples of Strange Mycelium from the former denizens of Fungara Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91377] = { id = 91377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn of the Dead", description = "It is obvious that something terrible has happened in the village. I can see the corpses of their largest specimens strewn across the southern reaches from here, but something is off about them too. Fungarians don't usually just leave the corpses of their kin lying about.\n\nAnd though I am watching from afar, I swear that some of them are... twitching.\n\nInvestigate. Find out what you can, and report back to me.", completion = "This is so much worse than I thought.\n\nWe have to find the source of this and destroy it before it infects something bigger and more dangerous than a fungarian.", objectives = "Investigate 5 Blooming Corpses in Fungara Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91378] = { id = 91378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Are Legend", description = "Whatever these things are, they're not fungarians. Not anymore. \n\nHar'alnor has enough to worry about with the Lightbloom as it is. It cannot afford to be trapped between its forces and these... things.\n\nDo what must be done. Destroy as many of them as you can.", progress = "Do not feel regret. These things are not alive anymore. Not in any way that matters.", completion = "You are quite the accomplished slayer of aberrations. Perhaps you should consider a vocation in monster-hunting.", objectives = "Kill 15 Decanimated fungarians in the northern reaches of Fungara Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91379] = { id = 91379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decayed Land", description = "As far as I can tell, these fungarians are all already dead. Something is animating their corpses from within, like puppets attached to unseen vines.\n\nThis fungal matter that's infesting them must be coming from somewhere... and judging from the size of the ones further north, we'll find plenty of it there. Find it, get rid of it, but for Aln'hara's sake don't breathe it in.", completion = "We've culled the worst of the growths to the north... but there are smaller ones already beginning to sprout. Where are they coming from?\n\nThere must be a source, and we'll have to find it if we mean to solve this thing.", objectives = "Destroy 8 growths of Fruiting Mycelium in Fungara Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91380] = { id = 91380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belly of the Beast", description = "I normally raise my beasts on a diet of raw, bloody carcasses and souls ripped asunder by the Void.\n\nBut we shall try your mortal ways.\n\nI hear you... cook? And that makes the treat better?\n\nDo this. Then, take him on a walk around the Howling Ridge. Even I know exercise is good for digestion.\n\nOnly the most ferocious of creatures is worthy of serving me. I hope neither you nor Fido disappoint me.", completion = "Is the beast's savagery growing?\n\nI'm sure I will begin to hear of his violence from those around the Howling Ridge.", objectives = "Feed and walk Fidoficus around the Howling Ridge to promote its growth and savagery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91381] = { id = 91381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reticent Evil", description = "I do not understand. We've searched high and low, north and south. Everywhere we go, we find animated corpses and small fruiting fungus, but where is the central body? Where is--\n\nOh, goddess. Of course.\n\nThe water, {class}. Check the water.", completion = "It is done, then.\n\nYou did well to survive untainted. The wilds are a dangerous place, and survival is never a guarantee.\n\nNow go. I must remain and ensure that these abominations cannot spread any further.", objectives = "Destroy the Agericus Decanimatus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91382] = { id = 91382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mighty and Superior", description = "The beast is fed and exercised. Imagine, mortal... one day his maw will grow to fit you inside it a thousand times over. \n\nNow, we will test his potential for true violence. \n\nThere is a beast that has laid claim to a den south of the Howling Ridge. \n\nFidoficus trusts you now. Go with him and bear witness to his might.", progress = "Fidoficus has grown fearsome, and perhaps you have claim to some of his growth.", completion = "Fidoficus will grow so terribly large, that it is he who will be walking you. \n\nOnly then will he be worthy of joining me as my attack behemoth.", objectives = "Bear witness to Fidoficus's savagery as it slays Den-Gorger Zitoc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91383] = { id = 91383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidy Up", description = "Captain Dawnrunner is fine, thank the sun. The only danger was... we didn't keep up on our chores.\n\nIt's not heroic, it's not romantic, but we can't go on with Farstrider Enclave in this state. The rangers here are overwhelmed. We can all pitch in to help them get it cleaned up again.\n\nI can't believe it all comes back to sweeping. That's what being a Farstrider is really about.", completion = "My rangers are earning their keep today, that's for certain.", objectives = "Clear out 5 Messy Nests and sweep up 5 Dusty Webs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91384] = { id = 91384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovery Mission", description = "We've been deploying Farstriders across the forest to fight the Amani, the Lightbloom, the Void... but for all our heroics, there's no one left to tend to the wildlife! Or maintain the building! Or keep track of supplies!\n\nAnd now our beloved Enclave looks like a hawkstrider pen. I've had enough!\n\nI may not be able to help, but I trust you all can gather anything that was taken and get this place looking respectable again.", progress = "If we want to be of any use to the rest of Eversong, first we must pick up after ourselves.", completion = "This is a good start. All it takes is a handful of us putting in a little effort.", objectives = "Retrieve 12 Scattered Supplies from around Farstrider Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91385] = { id = 91385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ranger's Spirit", description = "Taemin has proved himself as capable as any Farstrider today. But I'm afraid he might not see it that way.\n\nHe came to us with such lofty ideas about the rangers--all those swashbuckling adventure stories, all the romantic old legends. But at the end of the day, being a ranger is mostly... chores. Difficult, boring, important chores.\n\nWhy don't you go talk to him, and make sure he's not too disappointed?", progress = "The beauty of the forest? It never gets old.", completion = "The legends are real... Eversong must be pleased with us!", objectives = "Find Recruit Taemin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91386] = { id = 91386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mad to Measure", description = "These... tourists! These uncultured, ungrateful slobs!\n\nThis Vanguard of Light has brought a lot of business to Silvermoon, to be certain. But none of them actually appreciate what Thalassian craftsmanship means. They have no respect for the elven arts--they just want shiny, glittery souvenirs!\n\nI am no spring runner dancing for their amusement... but I can hardly turn them away, can I? Perhaps an assistant would make this atrocious task easier.", progress = "If only a single soul among these brutes showed any appreciation... alas, it seems even this small ask is too great.", completion = "All right... but only because I'm curious about the craftsmanship.\n\nIt'll take more than a little politeness to change my mind about these pernicious paladins.", objectives = "Assist Solwin Brightstitch with making clothes for Pushy Paladins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91388] = { id = 91388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncommon Threads", description = "Our patron--Gaari, I suppose--should count himself lucky. These mana wyrms produce the finest silk in Eversong. I know Magisters who would kill to have a robe trimmed in this, and yet here we are, using it for a mending job. Ah well.\n\nOnce the wyrms have eaten their fill of arcane energy, you can siphon the silk from them onto these bobbins.\n\nIf they are reluctant to release their silk, you may have to, ah... beat it out of them. But I've been assured it's entirely ethical.", progress = "This is the easy part, of course.", completion = "Ah... beautiful, glittering manasilk. So ripe with potential.", objectives = "Siphon 8 Full Bobbins of Manasilk from weakened wyrms in the North Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91389] = { id = 91389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clothes Make the Man", description = "It is not merely the material that makes an arcanoweave cloak so fine, but the weaving process itself.\n\nTo mend one, particularly one that has built up so much history and latent arcane energy... I am about to embark on a very dangerous bit of tailoring indeed. Finally, a real testament to my skills.\n\nI am excited. I hope nothing explodes. Meet me inside when you're prepared.", completion = "It is a thing of beauty... I am glad to know it is in the hands of someone who loves it so.", objectives = "Meet Solwin inside, then fend off any manifestations as he mends the cloak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91390] = { id = 91390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: What Remains of a Temple Broken" }
quests[91391] = { id = 91391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Scouting", description = "When the Alliance originally fought the Horde here, Kurdran served as a scout. He's still an excellent one. He took his gryphon to Blackrock Mountain to see what kind of forces we may be dealing with there.\n\nMeet up with him and see what kind of trouble you can cause.", completion = "Arator, {name}--thanks fer coming. Plenty o' Dark Horde in there.", objectives = "Meet Kurdran at Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91392] = { id = 91392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greedy Emissary" }
quests[91398] = { id = 91398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomes of Terror", description = "Knowledge is power, and de ogres been reading.\n\nBring me dey tomes so dey never grow dis powah again.", progress = "Get me de tomes.", completion = "Thank ya. Dese are going straight into de fire.", objectives = "Kill ogres in Atal'Kaldan and collect 4 tomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91399] = { id = 91399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of the Void", description = "De void elementals have one use.\n\nDe dust dey drop is useful for shadow magic rituals.\n\nCollect some for our tribe.", progress = "Don't worry, we been doin' dese rituals for centuries.", completion = "Our hunters gonna make good use of de powder. Thank ya.", objectives = "Kill void elementals and collect their ashes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91400] = { id = 91400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blades of the Fallen", description = "After de battle we left a lot of our weapons behind.\n\nPlease go collect dem so de Twilight's Blade doesn't get dem.", completion = "Thanks for collecting dem. Now our foes won't get de advantage of fine Amani crafting.", objectives = "Collect 12 Amani weapons from Atal'Kaldan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91401] = { id = 91401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead by Dusk", description = "De Twilight's Blade cultists have de audacity to try and take back our temple. Kill de peons and bring me their femurs.", progress = "Why femurs? None of ya business.", completion = "I got a plan for de bones. Thanks.", objectives = "Collect 20 femurs from Twilight's Blade cultists in Atal'Kaldan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[91402] = { id = 91402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ultra Deadly Ultradon", description = "I saw some of de void elementals doing a sketchy ritual in de center of the battlefield. It looked like dey were summoning some void creatures.\n\nMake sure whatever dey summon is dealt with.", completion = "Never seen one of dem before and hope I don't see dem again. Nicely done.", objectives = "Kill the Eminent Ultradon in the center of Atal'Kaldan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
